import{_ as s,l as i,o as e,c as l,v as o,p as n,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"焦点传感与晶圆形貌","description":"","frontmatter":{"title":"焦点传感与晶圆形貌","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focus-sensor-topography.md","filePath":"litho/focus-sensor-topography.md","lastUpdated":1789023840000}'),c={name:"litho/focus-sensor-topography.md"};function _(u,a,f,E,m,A){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="焦点传感与晶圆形貌" tabindex="-1">焦点传感与晶圆形貌 <a class="header-anchor" href="#焦点传感与晶圆形貌" aria-label="Permalink to &quot;焦点传感与晶圆形貌&quot;">​</a></h1><div class="epigraph"><p>调平给出刚体；扫描时形貌还在变。焦点传感要跟狭缝下那一条带的高度，而不是跟晶圆中心一个数。</p><footer>—— 对照扫描机 focus sensor；[离焦作为像差](/litho/defocus-as-aberration)</footer></div><p><a href="/litho/level-sensor-air-gauge">上一课</a>给出曝光前高度图。缺口是动态：扫描中热、夹盘吸真空、浸没力都会改形貌。本课钉焦点传感，不把对准标记提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bossung 对离焦敏感。狭缝瞬时视场只有毫米级宽，必须跟这条带的 Z。全局一张平面拟合不够：芯片区有 SRAM 高、逻辑低。把所有离焦写成镜头热，会漏掉片。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>狭缝附近光学或气隙焦点计，闭环到工件台 Z 与倾角。采样密度与扫描速度匹配。异常：真空泄漏造成局部鼓包，传感器看见但补偿行程不够就要停机。</p>',7)),(e(),n(p,null,{default:t(()=>[h(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E9%A2%84%E6%89%AB%E6%8F%8F%E5%BD%A2%E8%B2%8C%22%5D%20--%3E%20FF%5B%22%E5%89%8D%E9%A6%88%22%5D%0A%20%20SNS%5B%22%E7%8B%AD%E7%BC%9D%E7%84%A6%E7%82%B9%E8%AE%A1%22%5D%20--%3E%20FB%5B%22%E5%8F%8D%E9%A6%88%22%5D%0A%20%20FF%20--%3E%20Z%5B%22%E5%8F%B0%20Z%20%2F%20%E5%80%BE%E8%A7%92%22%5D%0A%20%20FB%20--%3E%20Z%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><span class="marginnote">浸没水的厚度变化也是光程。焦点计若在水外标定，水内要加偏移。流体课与本课在此相切。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离焦是波前的二次项。传感器把强度/相位对比或气隙换成 Z 误差。带宽必须覆盖扫描引起的形貌空间频率 × 速度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课对准传感器：XY 网格，不是 Z。两者标记可能相邻，光学通道分开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>焦点跟狭缝带，不跟片中心一个数。</li><li>前馈形貌 + 闭环焦点计。</li><li>出处：离焦课；扫描机 focus sensor 通识。</li></ul>',7))])}const b=s(c,[["render",_]]);export{T as __pageData,b as default};
